import java.util.*;

public class Main {
    static int maxProfitAssignment(int[] difficulty, int[] profit, int[] worker) {
        int n = difficulty.length;
        int total = 0;

        for (int ability : worker) {
            int best = 0;
            for (int i = 0; i < n; i++) {
                if (difficulty[i] <= ability) {
                    best = Math.max(best, profit[i]);
                }
            }
            total += best;
        }
        return total;
    }

    public static void main(String[] args) {
