import java.util.*;

public class Main {
    static int maxProfitAssignment(int[] difficulty, int[] profit, int[] worker) {
        int n = difficulty.length;
        Integer[] idx = new Integer[n];
        for (int i = 0; i < n; i++) idx[i] = i;
        Arrays.sort(idx, (a, b) -> difficulty[a] - difficulty[b]);

        int[] sortedWorker = worker.clone();
        Arrays.sort(sortedWorker);

        int i = 0, best = 0, total = 0;
        for (int ability : sortedWorker) {
            while (i < n && difficulty[idx[i]] <= ability) {
                best = Math.max(best, profit[idx[i]]);
                i++;
            }
            total += best;
        }
        return total;
    }

    public static void main(String[] args) {
        System.out.println(maxProfitAssignment(new int[]{2, 4, 6, 8, 10}, new int[]{10, 20, 30, 40, 50}, new int[]{4, 5, 6, 7}));
        System.out.println(maxProfitAssignment(new int[]{85, 47, 57}, new int[]{24, 66, 99}, new int[]{40, 25, 25}));
    }
}

