#include <bits/stdc++.h>
using namespace std;

int maxProfitAssignment(vector<int>& difficulty, vector<int>& profit, vector<int>& worker) {
    int n = difficulty.size();
    vector<pair<int,int>> jobs;
    for (int i = 0; i < n; i++) jobs.push_back({difficulty[i], profit[i]});
    sort(jobs.begin(), jobs.end());

    vector<int> sortedWorker = worker;
    sort(sortedWorker.begin(), sortedWorker.end());

    int i = 0, best = 0, total = 0;
    for (int ability : sortedWorker) {
        while (i < n && jobs[i].first <= ability) {
            best = max(best, jobs[i].second);
            i++;
        }
        total += best;
    }
    return total;
}

int main() {
    vector<int> difficulty1 = {2, 4, 6, 8, 10};
    vector<int> profit1 = {10, 20, 30, 40, 50};
    vector<int> worker1 = {4, 5, 6, 7};
    cout << maxProfitAssignment(difficulty1, profit1, worker1) << endl;
    vector<int> difficulty2 = {85, 47, 57};
    vector<int> profit2 = {24, 66, 99};
    vector<int> worker2 = {40, 25, 25};
    cout << maxProfitAssignment(difficulty2, profit2, worker2) << endl;
    return 0;
}
